import{_ as r,c as t,o as a,a5 as o}from"./chunks/framework.CUJoMJm2.js";const m=JSON.parse('{"title":"RPC Layer","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/rpc/index.md","filePath":"protocols/rpc/index.md","lastUpdated":1768070912000}'),n={name:"protocols/rpc/index.md"};function d(i,e,s,l,h,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/rpc.md for this page in Markdown format</div><h1 id="rpc-layer" tabindex="-1">RPC Layer <a class="header-anchor" href="#rpc-layer" aria-label="Permalink to “RPC Layer”">​</a></h1><blockquote><p><strong>Authority</strong>: Navigation (Non-normative)<br><strong>Purpose</strong>: Overview and navigation for RPC semantic layer.</p></blockquote><p>RPC is a <strong>semantic layer</strong> carried inside SBP Message frames. It does not define framing, transport, or security—those are handled by SBP and the session layer (SBRP/SBDP).</p><h2 id="relationship-to-sbp" tabindex="-1">Relationship to SBP <a class="header-anchor" href="#relationship-to-sbp" aria-label="Permalink to “Relationship to SBP”">​</a></h2><p>RPC envelopes are encoded in <code>MessageFrame.data</code>. Subject prefixes determine envelope semantics: <code>rpc/</code> for request/response, <code>event/</code> for notifications. See <a href="./envelope#subject-namespacing">envelope.md#subject-namespacing</a>.</p><h2 id="delegation" tabindex="-1">Delegation <a class="header-anchor" href="#delegation" aria-label="Permalink to “Delegation”">​</a></h2><p>This protocol delegates:</p><ul><li><strong>Wire format</strong>: Inherits SBP frame structure (see <a href="./../sbp/wire-format">sbp/wire-format.md</a>)</li><li><strong>Error codes</strong>: Reuses SBP protocol errors (1000-1999); defines application errors (2000+) in envelope.md</li><li><strong>Ordering</strong>: Inherits SBP ordering guarantees (see <a href="./../sbp/behavior">sbp/behavior.md</a>)</li></ul><p>This protocol defines:</p><ul><li><strong>Envelope format</strong>: See <a href="./envelope">envelope.md</a></li><li><strong>Correlation</strong>: See <a href="./behavior">behavior.md</a></li><li><strong>Subject namespacing</strong>: See <a href="./envelope">envelope.md</a></li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to “Errors”">​</a></h2><p>RPC defines error codes in the 1050–1099 range (see <a href="./envelope#error-codes">envelope.md</a>). It also uses:</p><ul><li>SBP protocol errors (1000–1049) — see <a href="./../sbp/errors">sbp/errors.md</a></li><li>Application errors (2000+) — defined per-method</li></ul><p>See <a href="./../architecture#error-code-ownership">Error Code Ownership</a> for the full allocation.</p><h2 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to “Documents”">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Status</th></tr></thead><tbody><tr><td><a href="./envelope">envelope.md</a></td><td>Normative</td></tr><tr><td><a href="./behavior">behavior.md</a></td><td>Normative</td></tr><tr><td><a href="./conformance">conformance.md</a></td><td>Supporting</td></tr><tr><td><a href="./streams">streams.md</a></td><td>Reserved</td></tr></tbody></table><h2 id="document-authority" tabindex="-1">Document Authority <a class="header-anchor" href="#document-authority" aria-label="Permalink to “Document Authority”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Primary</th><th>Supporting</th></tr></thead><tbody><tr><td>Envelope structure</td><td><a href="./envelope">envelope.md</a></td><td>—</td></tr><tr><td>Request/response semantics</td><td><a href="./behavior">behavior.md</a></td><td>—</td></tr><tr><td>Correlation</td><td><a href="./behavior">behavior.md</a></td><td>—</td></tr><tr><td>Test specification</td><td><a href="./conformance">conformance.md</a></td><td>—</td></tr></tbody></table><h2 id="recommended-reading-order" tabindex="-1">Recommended Reading Order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to “Recommended Reading Order”">​</a></h2><ol><li><strong>index.md</strong> (this document)</li><li><strong><a href="./envelope">envelope.md</a></strong> — wire format and validation</li><li><strong><a href="./behavior">behavior.md</a></strong> — semantics and timeouts</li></ol><h2 id="related-adrs" tabindex="-1">Related ADRs <a class="header-anchor" href="#related-adrs" aria-label="Permalink to “Related ADRs”">​</a></h2><ul><li>ADR-006: RPC envelope</li><li>ADR-010: RPC correlation (cid)</li></ul>',23)])])}const f=r(n,[["render",d]]);export{m as __pageData,f as default};
